import { Component, OnInit, SecurityContext } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { SafeHtml, DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { IAddOrUpdateProductModel, AddOrUpdateProductModel } from '../../../../../data/model/product/AddOrUpdateProductModel';
import { ProductService } from '../../../../../data/service/product/product.service';
import { G } from '../../../../../core/common/G';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { Urls } from '../../../../../core/common/Urls';

@Component({
  selector: 'app-add-product',
  templateUrl: './add-product.component.html',
  styleUrls: ['./add-product.component.scss']
})
export class AddProductComponent implements OnInit {

  priceType = 'price';
  shortDescription: SafeHtml;
  description: SafeHtml;
  imageUrl: any;
  addProductForm: FormGroup;
  productCategoryIds: number[] = [];
  mechanicCategories = [];
  tuningCategories = [];
  designeCategories = [];

  isGuaranteeShow = false;
  hasDiscountLargeOrder = false;
  discountByPercent = false;
  referable = false;
  referableByPercent = false;
  hasExtraDeliveryPrice = false;

  product: IAddOrUpdateProductModel;

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات کوتاه...',
    translate: 'no',
    sanitize: true
  };

  editorConfig2: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات اصلی...',
    translate: 'no',
    sanitize: true
  };

  constructor(
    private productService: ProductService,
    private fb: FormBuilder,
    public toastController: ToastController,
    private router: Router,
    public loadingController: LoadingController,
    private domSanitizer: DomSanitizer,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.addProductForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      referableReducePrice: [0, [Validators.min(0), Validators.max(90000000000)]],
      referableReducePercent: [0, [Validators.min(0), Validators.max(10000)]],
      sendTime: [3, [Validators.required, Validators.min(0), Validators.max(180)]],
      count: [0, [Validators.required, Validators.min(0), Validators.max(20000000)]],
      discountOrderCount: [0, [Validators.min(0), Validators.max(20000000)]],
      discountPrice: [0, [Validators.min(0), Validators.max(90000000000)]],
      maxDiscountPrice: [0, [Validators.min(0), Validators.max(90000000000)]],
      discountPercent: [0, [Validators.min(0), Validators.max(10000)]],
      maxDiscountPercent: [0, [Validators.min(0), Validators.max(10000)]],
      weight: [1000, [Validators.required, Validators.min(1), Validators.max(20000000)]],
      price: [0, [Validators.required, Validators.min(1000), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      imageName: ['http://localhost:4300/assets/images/in-progress.webp', [Validators.minLength(1), Validators.maxLength(1000000)]],
      imageNamePNG: ['http://localhost:4300/assets/images/in-progress.png', [Validators.minLength(1), Validators.maxLength(1000000)]],
      guaranteeDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      referableDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      shortDescription: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      description: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      isPostSend: [true, [Validators.required]],
      isSpecialPostSend: [true, [Validators.required]],
      isTipaxSend: [true, [Validators.required]],
      isTipaxSoRentSend: [true, [Validators.required]],
      isBurberrySend: [true, [Validators.required]],
      isBikeDeliverySend: [true, [Validators.required]],
      isOwnDeliverySend: [true, [Validators.required]],
      isExists: [true, [Validators.required]],
      isShow: [true, [Validators.required]],
      isCorrupt: [false, [Validators.required]],
      referable: [false, [Validators.required]],
      consumption: [false, [Validators.required]],
      hasSeveralDesigns: [false, [Validators.required]],
      extraDeliveryPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      hasExtraDeliveryPrice: [false, [Validators.required]],
      hasGuarantee: [false, [Validators.required]],
      hasPrivateDownloadLinks: [false, [Validators.required]],
      hasDiscountLargeOrder: [false, [Validators.required]],
      hasDiscountForEachOrder: [false, [Validators.required]],
      isUsed: [false, [Validators.required]],
      isFreeSend: [false, [Validators.required]],
      isWholesale: [false, [Validators.required]]
    });

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    G.getCourseCategory().subscribe(
      res => {
        if (res != null) {
          if (res.length > 0) {
            res.forEach(c => {

              if (c.parentId == 1) {
                this.mechanicCategories.push(c);
              } else if (c.parentId == 2) {
                this.tuningCategories.push(c);
              } else if (c.parentId == 3) {
                this.designeCategories.push(c);
              }
            });
          }
        }
      }
    );
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onPriceTypeChanged() {

    if (this.priceType === 'price') {
      this.addProductForm.setValue({
        name: this.addProductForm.value.name,
        price: this.addProductForm.value.price,
        offPrice: 0,
        imageName: this.addProductForm.value.imageName,
        imageNamePNG: this.addProductForm.value.imageNamePNG,
        shortDescription: this.addProductForm.value.shortDescription,
        description: this.addProductForm.value.description,
        referableReducePrice: this.addProductForm.value.referableReducePrice,
        referableReducePercent: this.addProductForm.value.referableReducePercent,
        sendTime: this.addProductForm.value.sendTime,
        count: this.addProductForm.value.count,
        discountOrderCount: this.addProductForm.value.discountOrderCount,
        discountPrice: this.addProductForm.value.discountPrice,
        maxDiscountPrice: this.addProductForm.value.maxDiscountPrice,
        discountPercent: this.addProductForm.value.discountPercent,
        maxDiscountPercent: this.addProductForm.value.maxDiscountPercent,
        weight: this.addProductForm.value.weight,
        guaranteeDescription: this.addProductForm.value.guaranteeDescription,
        referableDescription: this.addProductForm.value.referableDescription,
        isPostSend: this.addProductForm.value.isPostSend,
        isSpecialPostSend: this.addProductForm.value.isSpecialPostSend,
        isOwnDeliverySend: this.addProductForm.value.isOwnDeliverySend,
        isTipaxSend: this.addProductForm.value.isTipaxSend,
        isTipaxSoRentSend: this.addProductForm.value.isTipaxSoRentSend,
        isBurberrySend: this.addProductForm.value.isBurberrySend,
        isBikeDeliverySend: this.addProductForm.value.isBikeDeliverySend,
        isExists: this.addProductForm.value.isExists,
        isShow: this.addProductForm.value.isShow,
        extraDeliveryPrice: this.addProductForm.value.extraDeliveryPrice,
        hasExtraDeliveryPrice: this.addProductForm.value.hasExtraDeliveryPrice,
        isCorrupt: this.addProductForm.value.isCorrupt,
        referable: this.addProductForm.value.referable,
        consumption: this.addProductForm.value.consumption,
        hasSeveralDesigns: this.addProductForm.value.hasSeveralDesigns,
        hasGuarantee: this.addProductForm.value.hasGuarantee,
        hasPrivateDownloadLinks: this.addProductForm.value.hasPrivateDownloadLinks,
        hasDiscountLargeOrder: this.addProductForm.value.hasDiscountLargeOrder,
        hasDiscountForEachOrder: this.addProductForm.value.hasDiscountForEachOrder,
        isUsed: this.addProductForm.value.isUsed,
        isFreeSend: this.addProductForm.value.isFreeSend,
        isWholesale: this.addProductForm.value.isWholesale
      });
    } else if (this.priceType === 'offPrice') {
      this.addProductForm.setValue({
        name: this.addProductForm.value.name,
        price: this.addProductForm.value.price,
        offPrice: '',
        imageName: this.addProductForm.value.imageName,
        imageNamePNG: this.addProductForm.value.imageNamePNG,
        shortDescription: this.addProductForm.value.shortDescription,
        description: this.addProductForm.value.description,
        referableReducePrice: this.addProductForm.value.referableReducePrice,
        referableReducePercent: this.addProductForm.value.referableReducePercent,
        sendTime: this.addProductForm.value.sendTime,
        count: this.addProductForm.value.count,
        discountOrderCount: this.addProductForm.value.discountOrderCount,
        discountPrice: this.addProductForm.value.discountPrice,
        maxDiscountPrice: this.addProductForm.value.maxDiscountPrice,
        discountPercent: this.addProductForm.value.discountPercent,
        maxDiscountPercent: this.addProductForm.value.maxDiscountPercent,
        weight: this.addProductForm.value.weight,
        guaranteeDescription: this.addProductForm.value.guaranteeDescription,
        referableDescription: this.addProductForm.value.referableDescription,
        isPostSend: this.addProductForm.value.isPostSend,
        isSpecialPostSend: this.addProductForm.value.isSpecialPostSend,
        extraDeliveryPrice: this.addProductForm.value.extraDeliveryPrice,
        hasExtraDeliveryPrice: this.addProductForm.value.hasExtraDeliveryPrice,
        isTipaxSend: this.addProductForm.value.isTipaxSend,
        isTipaxSoRentSend: this.addProductForm.value.isTipaxSoRentSend,
        isBurberrySend: this.addProductForm.value.isBurberrySend,
        isBikeDeliverySend: this.addProductForm.value.isBikeDeliverySend,
        isOwnDeliverySend: this.addProductForm.value.isOwnDeliverySend,
        isExists: this.addProductForm.value.isExists,
        isShow: this.addProductForm.value.isShow,
        isCorrupt: this.addProductForm.value.isCorrupt,
        referable: this.addProductForm.value.referable,
        consumption: this.addProductForm.value.consumption,
        hasSeveralDesigns: this.addProductForm.value.hasSeveralDesigns,
        hasGuarantee: this.addProductForm.value.hasGuarantee,
        hasPrivateDownloadLinks: this.addProductForm.value.hasPrivateDownloadLinks,
        hasDiscountLargeOrder: this.addProductForm.value.hasDiscountLargeOrder,
        hasDiscountForEachOrder: this.addProductForm.value.hasDiscountForEachOrder,
        isUsed: this.addProductForm.value.isUsed,
        isFreeSend: this.addProductForm.value.isFreeSend,
        isWholesale: this.addProductForm.value.isWholesale
      });
    }
  }

  onCategoryChecked(productCategoryId: number | string) {

    if (this.productCategoryIds.find(c => c == productCategoryId) == null) {

      this.productCategoryIds.push(+productCategoryId);
    } else {
      this.productCategoryIds.splice(this.productCategoryIds.findIndex(c => c == productCategoryId), 1);
    }

  }

  onGuaranteeClicked(checked) {

    this.isGuaranteeShow = checked.detail.checked;
  }

  onhasDiscountLargeOrderClicked(checked) {

    this.hasDiscountLargeOrder = checked.detail.checked;
  }

  onDiscountByPercentClicked(checked) {

    this.discountByPercent = checked.detail.checked;
  }

  onReferableClicked(checked) {

    this.referable = checked.detail.checked;
  }

  onReferableByPercentClicked(checked) {

    this.referableByPercent = checked.detail.checked;
  }

  onExtraDeliveryPriceClicked(checked) {

    this.hasExtraDeliveryPrice = checked.detail.checked;
  }

  onAdd() {

    if (this.addProductForm.valid) {

      if (this.productCategoryIds.length < 1) {

        SharedIonic.toast(this.toastController, 'گروهی انتخاب نشده است');
        return;
      }

      if (+this.addProductForm.value.offPrice > +this.addProductForm.value.price) {

        SharedIonic.toast(this.toastController, 'تخفیف بیشتر از قیمت اصلی است');
        return;
      }

      SharedIonic.loading(this.loadingController);

      this.shortDescription = this.addProductForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.addProductForm.value.descriptionHtmlContent);

      this.product =
        new AddOrUpdateProductModel(
          null,
          this.addProductForm.value.name,
          !this.referable ? 0 : (this.referableByPercent ? 0 : this.addProductForm.value.referableReducePrice),
          !this.referable ? 0 : (!this.referableByPercent ? 0 : this.addProductForm.value.referableReducePercent),
          this.addProductForm.value.sendTime,
          this.addProductForm.value.count,
          this.addProductForm.value.price,
          this.addProductForm.value.offPrice,
          this.addProductForm.value.guaranteeDescription,
          this.addProductForm.value.referableDescription,
          this.addProductForm.value.shortDescription,
          this.addProductForm.value.description,
          this.addProductForm.value.imageName,
          this.addProductForm.value.imageNamePNG,
          this.addProductForm.value.isPostSend,
          this.addProductForm.value.isTipaxSend,
          this.addProductForm.value.isTipaxSoRentSend,
          this.addProductForm.value.isBurberrySend,
          this.addProductForm.value.isBikeDeliverySend,
          this.addProductForm.value.isExists,
          this.addProductForm.value.isShow,
          this.addProductForm.value.isCorrupt,
          false,
          false,
          this.addProductForm.value.referable,
          this.addProductForm.value.consumption,
          this.addProductForm.value.hasSeveralDesigns,
          this.addProductForm.value.hasGuarantee,
          this.addProductForm.value.hasPrivateDownloadLinks,
          this.addProductForm.value.hasDiscountLargeOrder,
          !this.hasDiscountLargeOrder ? false : this.addProductForm.value.hasDiscountForEachOrder,
          this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.addProductForm.value.discountPrice,
          this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.addProductForm.value.maxDiscountPrice,
          !this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.addProductForm.value.discountPercent,
          !this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.addProductForm.value.maxDiscountPercent,
          !this.hasDiscountLargeOrder ? 0 : this.addProductForm.value.discountOrderCount,
          this.priceType == 'offPrice',
          100,
          this.addProductForm.value.weight,
          false,
          false,
          this.addProductForm.value.isUsed,
          this.addProductForm.value.isFreeSend,
          this.addProductForm.value.isWholesale,
          this.productCategoryIds,
          this.addProductForm.value.isOwnDeliverySend,
          this.addProductForm.value.isSpecialPostSend,
          this.addProductForm.value.hasExtraDeliveryPrice,
          this.hasExtraDeliveryPrice ? this.addProductForm.value.extraDeliveryPrice : 0
        );

      this.productService.AddOrUpdateProduct(this.product).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.router.navigateByUrl(Urls.SellerPanelUrl);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
